    def is_good(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    first, second = lst[0], lst[1]

    # Check both concatenation orders
    if is_good(first + second) or is_good(second + first):
        return 'Yes'
    else:
        return 'No'

